// The trial state machine. Holds a `state` object ({cases, seen, stats}) that
// the server persists as JSON. Effects (Stripe, email, alerts) are injected so
// the whole thing is testable without a network.
import { planTrial, replan, mergePolicy, formatMoney } from "./trial.mjs";
import { renderEmail } from "./templates.mjs";

const DAY = 86400000;
const MAX_SEEN = 500;
const MAX_ATTEMPTS = 3;

export function newState() {
  const g = () => ({ converted: 0, lost: 0 });
  return { cases: {}, seen: [], stats: { emails: 0, extensions: 0, card: g(), nocard: g() } };
}

function closeCase(state, c, outcome, now) {
  if (c.status !== "open") return;
  c.status = outcome; c.closedAt = now;
  for (const s of c.steps) if (s.status === "pending") s.status = "skipped";
  if (outcome === "converted" || outcome === "lost") state.stats[c.cardAtStart ? "card" : "nocard"][outcome] += 1;
}

const unix = (s) => (Number.isFinite(Number(s)) ? Number(s) * 1000 : null);

function priceOf(sub) {
  const item = sub.items?.data?.[0];
  const price = item?.price || item?.plan || {};
  const unit = price.unit_amount ?? price.amount ?? 0;
  return { amountMinor: unit * (item?.quantity || 1), currency: price.currency || sub.currency || "usd", interval: price.recurring?.interval || price.interval || "month" };
}

// Feed one verified Stripe event in. `hasCard` is resolved by the caller (it can
// need an API call) and only used when a trial is first seen or its card state
// is re-read.
export function applyEvent(state, event, { now, policy, hasCard }) {
  if (state.seen.includes(event.id)) return { ignored: "duplicate" };
  state.seen.push(event.id);
  if (state.seen.length > MAX_SEEN) state.seen.splice(0, state.seen.length - MAX_SEEN);
  const obj = event.data?.object || {};
  switch (event.type) {
    case "customer.subscription.created": case "customer.subscription.updated": case "customer.subscription.trial_will_end": {
      const id = obj.id;
      if (!id) return { ignored: "no subscription id" };
      const c = state.cases[id];
      const end = unix(obj.trial_end);
      if (obj.status === "trialing" && end) {
        const card = hasCard ?? Boolean(obj.default_payment_method);
        if (!c) {
          const start = unix(obj.trial_start) ?? now;
          if (end <= now) return { ignored: "trial already over" };
          const price = priceOf(obj);
          const open = {
            subscription: id, customer: typeof obj.customer === "string" ? obj.customer : obj.customer?.id, email: obj.customer_email || null, name: null,
            trialStart: start, trialEnd: end, hasCard: card, cardAtStart: card, extensions: 0, ...price, status: "open", steps: [], log: [], t0: now,
          };
          open.steps = planTrial({ start, end, hasCard: card, policy, now });
          state.cases[id] = open;
          return { opened: id, mode: card ? "card" : "nocard", steps: open.steps.length };
        }
        if (c.status !== "open") return { ignored: `case is ${c.status}` };
        const moved = end !== c.trialEnd, carded = card !== c.hasCard;
        if (!moved && !carded) return { ignored: "no change" };
        // A trial moved by the merchant (or by us) re-plans from the new end.
        if (moved) c.trialEnd = end;
        c.hasCard = card;
        c.steps = replan(c, { now, policy });
        return { updated: id, moved, cardAdded: carded && card, mode: card ? "card" : "nocard" };
      }
      if (c && c.status === "open" && ["active", "past_due", "incomplete"].includes(obj.status)) {
        closeCase(state, c, "converted", now);
        return { closed: id, outcome: "converted" };
      }
      if (c && c.status === "open" && ["canceled", "incomplete_expired", "paused", "unpaid"].includes(obj.status)) {
        closeCase(state, c, "lost", now);
        return { closed: id, outcome: "lost" };
      }
      return { ignored: c ? `status ${obj.status}` : "not a trial" };
    }
    case "customer.subscription.deleted": case "customer.subscription.paused": {
      const c = state.cases[obj.id];
      if (c) closeCase(state, c, "lost", now);
      return c ? { closed: obj.id, outcome: "lost" } : { ignored: "no case" };
    }
    case "invoice.paid": case "invoice.payment_succeeded": {
      const sub = obj.subscription || obj.parent?.subscription_details?.subscription;
      const c = sub && state.cases[sub];
      if (c && obj.amount_paid > 0) { closeCase(state, c, "converted", now); return { closed: sub, outcome: "converted" }; }
      return { ignored: "no case" };
    }
    case "payment_method.attached": {
      // A card was added by a customer in a card-less trial: flip them to the
      // card plan (the heads-up email replaces the begging).
      let n = 0;
      for (const c of Object.values(state.cases)) {
        if (c.status === "open" && c.customer === obj.customer && !c.hasCard) {
          c.hasCard = true; c.steps = replan(c, { now, policy }); n++;
        }
      }
      return { cardAdded: n };
    }
    default:
      return { ignored: event.type };
  }
}

export function dueSteps(state, now) {
  const out = [];
  for (const c of Object.values(state.cases)) {
    if (c.status !== "open") continue;
    for (const s of c.steps) if (s.status === "pending" && s.at <= now) out.push({ c, s });
  }
  return out.sort((a, b) => a.s.at - b.s.at);
}

const dateOf = (ms) => new Date(ms).toISOString().slice(0, 10);

function emailVars(c, deps, extra = {}) {
  return {
    name: c.name || "there", amount: formatMoney(c.amountMinor, c.currency), interval: c.interval, company: deps.company || "our team",
    address: deps.address || "", end_date: dateOf(c.trialEnd), manage_url: deps.manageUrl(c),
    tips_line: deps.tipsUrl ? ` A good place to start: ${deps.tipsUrl}` : "", ...extra,
  };
}

// Run everything due. deps: {stripe, sendEmail, alert, manageUrl, company, address, tipsUrl, policy, dryRun}
export async function tick(state, now, deps) {
  const policy = mergePolicy(deps.policy);
  const done = [];
  for (const { c, s } of dueSteps(state, now)) {
    if (c.status !== "open") continue;
    const note = (msg) => { c.log.push({ at: now, step: s.id, msg }); done.push(`${c.subscription} ${s.id}: ${msg}`); };
    try {
      if (c.trialEnd <= now) { s.status = "skipped"; note("trial already ended"); continue; }
      if (s.kind === "email") {
        if (now - s.at > policy.staleHours * 3600000) { s.status = "skipped"; note("too late to send, skipped"); continue; }
        if (!c.email) {
          // The subscription event rarely carries the address; fetch it once.
          if (deps.stripe?.customerEmail) { const e = await deps.stripe.customerEmail(c.customer).catch(() => null); if (e) { c.email = e.email; c.name = c.name || e.name; } }
          if (!c.email) { s.status = "skipped"; note("no customer email"); continue; }
        }
        const mail = renderEmail(s.template, emailVars(c, deps, s.extraDays ? { extra_days: s.extraDays } : {}));
        if (!deps.dryRun) await deps.sendEmail({ to: c.email, ...mail });
        s.status = "done"; state.stats.emails += 1; note(deps.dryRun ? `dry run: would email ${s.template}` : `emailed ${s.template}`);
      } else if (s.kind === "extend") {
        if (c.hasCard || c.extensions >= 1) { s.status = "skipped"; note("card added or already extended"); continue; }
        const newEnd = c.trialEnd + s.days * DAY;
        if (!deps.dryRun) {
          const sub = await deps.stripe.getSubscription(c.subscription);
          if (sub.status !== "trialing" || sub.default_payment_method) { s.status = "skipped"; note(`subscription is ${sub.status}${sub.default_payment_method ? " with a card" : ""}`); continue; }
          await deps.stripe.extendTrial(c.subscription, Math.floor(newEnd / 1000), `tc-${c.subscription}-extend`);
        }
        s.status = "done"; c.extensions += 1; c.trialEnd = newEnd; state.stats.extensions += 1;
        c.steps = replan(c, { now, policy });
        c.steps.push({ id: `extended-x${c.extensions}`, kind: "email", template: "extended", at: now, status: "pending", extraDays: s.days });
        note(deps.dryRun ? `dry run: would extend the trial ${s.days} days` : `trial extended ${s.days} days to ${dateOf(newEnd)}`);
      }
    } catch (e) {
      s.tries = (s.tries || 0) + 1;
      note(`error: ${e.message}`);
      if (s.tries >= MAX_ATTEMPTS) { s.status = "failed"; await deps.alert?.(`trial-converter: step ${s.id} on ${c.subscription} failed ${MAX_ATTEMPTS} times: ${e.message}`).catch(() => {}); }
      else s.at = now + 5 * 60000 * s.tries;
    }
  }
  return done;
}

const ratio = (g) => (g.converted + g.lost ? Math.round((1000 * g.converted) / (g.converted + g.lost)) / 10 : null);

export function summary(state) {
  const open = Object.values(state.cases).filter((c) => c.status === "open");
  const s = state.stats;
  return {
    open: open.length, openWithoutCard: open.filter((c) => !c.hasCard).length,
    converted: s.card.converted + s.nocard.converted, lost: s.card.lost + s.nocard.lost,
    conversionPctWithCard: ratio(s.card), conversionPctWithoutCard: ratio(s.nocard),
    emails: s.emails, extensions: s.extensions,
  };
}

server.mjs.text:
#!/usr/bin/env node
// Self-hosted Stripe trial-to-paid conversion. Zero dependencies.
//   STRIPE_SECRET_KEY=rk_... STRIPE_WEBHOOK_SECRET=whsec_... ADMIN_KEY=... \
//   LINK_SECRET=... PUBLIC_URL=https://trials.example.com RESEND_API_KEY=... \
//   MAIL_FROM="Acme <hello@example.com>" COMPANY_NAME=Acme node server.mjs
// DRY_RUN defaults to true: it records and logs what it would do and touches
// neither Stripe nor your customers until you set DRY_RUN=false.
import http from "node:http";
import fs from "node:fs";
import { createHmac, timingSafeEqual } from "node:crypto";
import { verifySignature, createStripe } from "./stripe.mjs";
import { ADMIN_HTML, ADMIN_CSP } from "./admin.mjs";
import { applyEvent, tick, summary, newState } from "./engine.mjs";

const env = process.env;

export function linkToken(secret, customer) {
  const body = Buffer.from(customer).toString("base64url");
  return `${body}.${createHmac("sha256", secret).update(body).digest("base64url")}`;
}
export function customerFromToken(secret, token) {
  const [body, sig] = String(token).split(".");
  if (!body || !sig) return null;
  const want = createHmac("sha256", secret).update(body).digest();
  const got = Buffer.from(sig, "base64url");
  if (got.length !== want.length || !timingSafeEqual(got, want)) return null;
  return Buffer.from(body, "base64url").toString();
}

const readBody = (req, max = 1_000_000) => new Promise((resolve, reject) => {
  let size = 0; const chunks = [];
  req.on("data", (c) => { size += c.length; if (size > max) { reject(Object.assign(new Error("too large"), { status: 413 })); req.destroy(); } else chunks.push(c); });
  req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
  req.on("error", reject);
});

const bearerOk = (req, key) => {
  const a = Buffer.from(req.headers.authorization || "");
  const b = Buffer.from(`Bearer ${key}`);
  return Boolean(key) && a.length === b.length && timingSafeEqual(a, b);
};

// cfg: {state, save, stripe, webhookSecret, linkSecret, adminKey, publicUrl, policy, dryRun, now}
export function handler(cfg) {
  const now = cfg.now || Date.now;
  return async (req, res) => {
    const url = new URL(req.url, "http://x");
    const send = (code, body, type = "text/plain") => { res.writeHead(code, { "content-type": type }); res.end(typeof body === "string" ? body : JSON.stringify(body, null, 2)); };
    try {
      if (url.pathname === "/healthz") return send(200, "ok\n");
      if (req.method === "POST" && url.pathname === "/webhook/stripe") {
        const raw = await readBody(req);
        if (!verifySignature(raw, req.headers["stripe-signature"], cfg.webhookSecret, Math.floor(now() / 1000))) return send(400, "bad signature\n");
        const event = JSON.parse(raw);
        let hasCard;
        if (event.type?.startsWith("customer.subscription.") && event.data?.object?.status === "trialing") hasCard = await cfg.stripe.hasCardFor(event.data.object).catch(() => undefined);
        const result = applyEvent(cfg.state, event, { now: now(), policy: cfg.policy, hasCard });
        cfg.save();
        return send(200, result, "application/json");
      }
      if (req.method === "GET" && url.pathname.startsWith("/manage/")) {
        const customer = customerFromToken(cfg.linkSecret, decodeURIComponent(url.pathname.slice(8)));
        if (!customer) return send(404, "link not valid\n");
        const to = await cfg.stripe.portalUrl(customer, cfg.publicUrl || "https://stripe.com");
        res.writeHead(302, { location: to }); return res.end();
      }
      if (req.method === "GET" && url.pathname === "/admin") {
        res.writeHead(200, { "content-type": "text/html; charset=utf-8", "content-security-policy": ADMIN_CSP, "cache-control": "no-store", "x-content-type-options": "nosniff" });
        return res.end(ADMIN_HTML);
      }
      if (url.pathname === "/v1/summary" || url.pathname === "/v1/cases") {
        if (!bearerOk(req, cfg.adminKey)) return send(401, "admin key required\n");
        if (url.pathname === "/v1/summary") return send(200, { dryRun: cfg.dryRun, ...summary(cfg.state) }, "application/json");
        return send(200, Object.values(cfg.state.cases).map(({ steps, log, email, ...c }) => ({ ...c, steps: steps.map((s) => ({ id: s.id, kind: s.kind, at: new Date(s.at).toISOString(), status: s.status })), log: log.slice(-5) })), "application/json");
      }
      return send(404, "not found\n");
    } catch (e) {
      console.error("request failed:", e.message);
      return send(e.status || 500, "error\n");
    }
  };
}

function readJson(path, fallback) {
  try { return JSON.parse(fs.readFileSync(path, "utf8")); } catch (e) { if (e.code === "ENOENT") return fallback; throw e; }
}

async function sendResend(msg) {
  const res = await fetch("https://api.resend.com/emails", {
    method: "POST", headers: { authorization: `Bearer ${env.RESEND_API_KEY}`, "content-type": "application/json" },
    body: JSON.stringify({ from: env.MAIL_FROM, to: [msg.to], subject: msg.subject, text: msg.text }),
  });
  if (!res.ok) throw new Error(`resend ${res.status}`);
}

async function alert(text) {
  console.log(text);
  if (env.ALERT_WEBHOOK_URL) await fetch(env.ALERT_WEBHOOK_URL, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ text, content: text }) }).catch(() => {});
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const missing = ["STRIPE_SECRET_KEY", "STRIPE_WEBHOOK_SECRET", "ADMIN_KEY", "LINK_SECRET"].filter((k) => !env[k]);
  if (missing.length) { console.error(`missing env: ${missing.join(", ")}`); process.exit(1); }
  const dryRun = env.DRY_RUN !== "false";
  const statePath = env.STATE || "state.json";
  const state = readJson(statePath, newState());
  const save = () => { fs.writeFileSync(`${statePath}.tmp`, JSON.stringify(state)); fs.renameSync(`${statePath}.tmp`, statePath); };
  const stripe = createStripe({ key: env.STRIPE_SECRET_KEY });
  const policy = { ...(env.POLICY_JSON ? JSON.parse(env.POLICY_JSON) : {}), ...(env.EXTEND_DAYS ? { extendDays: Number(env.EXTEND_DAYS) } : {}) };
  const publicUrl = (env.PUBLIC_URL || "").replace(/\/$/, "");
  const deps = {
    stripe, policy, dryRun, alert, sendEmail: sendResend, company: env.COMPANY_NAME, address: env.COMPANY_ADDRESS, tipsUrl: env.TIPS_URL,
    manageUrl: (c) => (publicUrl ? `${publicUrl}/manage/${linkToken(env.LINK_SECRET, c.customer)}` : ""),
  };
  if (!dryRun && (!env.RESEND_API_KEY || !env.MAIL_FROM)) { console.error("DRY_RUN=false needs RESEND_API_KEY and MAIL_FROM"); process.exit(1); }
  if (!dryRun && !publicUrl) { console.error("DRY_RUN=false needs PUBLIC_URL (emails link to it)"); process.exit(1); }
  setInterval(async () => { try { const log = await tick(state, Date.now(), deps); log.forEach((l) => console.log(l)); if (log.length) save(); } catch (e) { console.error("tick failed:", e.message); } }, 60000).unref?.();
  const cfg = { state, save, stripe, webhookSecret: env.STRIPE_WEBHOOK_SECRET, linkSecret: env.LINK_SECRET, adminKey: env.ADMIN_KEY, publicUrl, policy, dryRun };
  http.createServer(handler(cfg)).listen(Number(env.PORT || 8080), () => console.log(`trial-converter on :${env.PORT || 8080} (${dryRun ? "DRY RUN" : "LIVE"})`));
}

stripe.mjs.text:
// Minimal Stripe pieces, no SDK: webhook signature verification and the few API
// calls trial conversion needs. Use a restricted key (rk_...) with Customers:
// read, Customer portal: write, Subscriptions: read, and Subscriptions: write
// only if you enable trial extensions (EXTEND_DAYS).
import { createHmac, timingSafeEqual } from "node:crypto";

export function verifySignature(rawBody, header, secret, nowSec = Math.floor(Date.now() / 1000), toleranceSec = 300) {
  if (!header || !secret) return false;
  const parts = String(header).split(",").map((p) => p.trim().split("="));
  const t = parts.find(([k]) => k === "t")?.[1];
  const sigs = parts.filter(([k]) => k === "v1").map(([, v]) => v);
  if (!t || !sigs.length || !/^\d+$/.test(t)) return false;
  if (Math.abs(nowSec - Number(t)) > toleranceSec) return false;
  const want = createHmac("sha256", secret).update(`${t}.${rawBody}`).digest();
  return sigs.some((s) => {
    const got = Buffer.from(s, "hex");
    return got.length === want.length && timingSafeEqual(got, want);
  });
}

export function signPayload(rawBody, secret, tSec) {
  return `t=${tSec},v1=${createHmac("sha256", secret).update(`${tSec}.${rawBody}`).digest("hex")}`;
}

const form = (obj) => new URLSearchParams(Object.entries(obj).filter(([, v]) => v !== undefined && v !== null)).toString();

export function createStripe({ key, fetchImpl = fetch, base = "https://api.stripe.com" }) {
  async function call(method, path, body, headers = {}) {
    const res = await fetchImpl(`${base}${path}`, {
      method,
      headers: { authorization: `Bearer ${key}`, "content-type": "application/x-www-form-urlencoded", ...headers },
      body: body ? form(body) : undefined,
    });
    const json = await res.json().catch(() => ({}));
    if (!res.ok) {
      const e = new Error(json?.error?.message || `stripe ${res.status}`);
      e.status = res.status; e.code = json?.error?.code; e.body = json;
      throw e;
    }
    return json;
  }
  const customer = (id) => call("GET", `/v1/customers/${encodeURIComponent(id)}`);
  return {
    getSubscription: (id) => call("GET", `/v1/subscriptions/${encodeURIComponent(id)}`),
    customerEmail: async (id) => { const c = await customer(id); return c.email ? { email: c.email, name: c.name || null } : null; },
    // A trial has a card if the subscription names one or the customer has a
    // default. Card-less trials (no payment method collected up front) have neither.
    async hasCardFor(sub) {
      if (sub.default_payment_method || sub.default_source) return true;
      const id = typeof sub.customer === "string" ? sub.customer : sub.customer?.id;
      if (!id) return false;
      const c = await customer(id);
      return Boolean(c.invoice_settings?.default_payment_method || c.default_source);
    },
    // Portal session URLs are short-lived, so emails link to this service's own
    // /manage/<token> route, which mints a fresh session on click.
    portalUrl: async (cust, returnUrl) => (await call("POST", "/v1/billing_portal/sessions", { customer: cust, return_url: returnUrl })).url,
    extendTrial: (id, trialEndUnix, idempotencyKey) => call("POST", `/v1/subscriptions/${encodeURIComponent(id)}`, { trial_end: trialEndUnix, proration_behavior: "none" }, { "idempotency-key": idempotencyKey }),
  };
}

